from lumina_compiler import LuminaAgent

class MultiplexerAgent(LuminaAgent):
    def configure(self):
        self.inputs = {
            "a": "Basin_A",
            "b": "Basin_B",
            "sel": "Basin_Sel"
        }
        self.outputs = {
            "out": "Basin_Out"
        }

    def flow(self):
        self.out = (self.a & ~self.sel) | (self.b & self.sel)

from lumina_compiler import LuminaAgent

class SRLatchAgent(LuminaAgent):
    def configure(self):
        self.inputs = {"s": "Basin_S", "r": "Basin_R"}
        self.outputs = {"q": "Basin_Q", "qbar": "Basin_Qbar"}

    def flow(self):
        self.q = ~(self.r | self.qbar)
        self.qbar = ~(self.s | self.q)
